/**
 * Typed client for the Onyx Platform API, generated from the FastAPI OpenAPI contract.
 *
 * `schema.ts` and `openapi.json` are generated by `make api-client`; never edit them by hand.
 * Business rules live in the API: this package only carries types and transport.
 */
import createClient, { type Client } from "openapi-fetch";

import type { components, operations, paths } from "./schema";

export type { components, operations, paths };

export type Schemas = components["schemas"];
export type ApiError = Schemas["ApiError"];
export type ErrorCode = Schemas["ErrorCode"];
export type Permission = Schemas["Permission"];
export type Role = Schemas["MembershipRole"];
export type Me = Schemas["MeResponse"];
export type Workspace = Schemas["WorkspaceOut"];
export type WorkspaceUpdate = Schemas["WorkspaceUpdate"];
export type WorkspaceSummary = Schemas["WorkspaceSummary"];

export type ApiClient = Client<paths>;

export const REQUEST_ID_HEADER = "X-Request-ID";

export type ApiClientOptions = {
  /** API origin, e.g. https://api.onyx.mt. Paths already include the `/v1` prefix. */
  baseUrl: string;
  accessToken?: string;
  /** Correlates the caller's logs with the API's logs and audit entries. */
  requestId?: string;
  fetch?: typeof globalThis.fetch;
};

export function createApiClient(options: ApiClientOptions): ApiClient {
  const headers: Record<string, string> = {};
  if (options.accessToken) headers.Authorization = `Bearer ${options.accessToken}`;
  if (options.requestId) headers[REQUEST_ID_HEADER] = options.requestId;
  return createClient<paths>({ baseUrl: options.baseUrl, headers, fetch: options.fetch });
}

/** The standard error body, if `body` is one. */
export function apiErrorOf(body: unknown): ApiError | undefined {
  if (typeof body !== "object" || body === null || !("error" in body)) return undefined;
  const error = (body as { error: unknown }).error;
  if (typeof error !== "object" || error === null) return undefined;
  if (typeof (error as { code?: unknown }).code !== "string") return undefined;
  return error as ApiError;
}
